#include <iostream>
#include <cmath>
#include <cstring>
#include <algorithm>

using namespace std;

typedef long long ll;

const int MODULUS = 1e9 + 7;

int mod = MODULUS;

int add_mod(int a, int b) { return ((a += b) < mod ? a : a - mod); }
int mul_mod(int a, int b) { return (ll) a * b % mod; }
int fast_pow(int base, int exp) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) result = mul_mod(result, base);
        base = mul_mod(base, base);
        exp >>= 1;
    }
    return result;
}

int P[1000001];

int compute_beb(int a, int m) {
    memset(P, -1, sizeof P);
    int s = (int) sqrt(m);
    mod = m;
    int r = a % m;
    int d = fast_pow(a, m - 2);
    for (int i = 0; i <= s; ++i) {
        if (P[r] == -1) P[r] = i;
        r = mul_mod(r, d);
        if (r == 1) { mod = MODULUS; return i + 1; }
    }
    d = fast_pow(a, s);
    r = d;
    for (int i = 1; i <= s; ++i) {
        if (P[r] > -1) {
            mod = MODULUS;
            return s * i + P[r];
        }
        r = mul_mod(r, d);
    }
    return -1;
}

int main() {
    int p, k; cin >> p >> k;
    if (k == 1) cout << fast_pow(p, p);
    else if (k == 0) cout << fast_pow(p, p - 1);
    else cout << fast_pow(p, (p - 1) / compute_beb(k, p));
    return 0;
}
